#!/usr/bin/env python3
"""Правки по итогам сверки цитат с источниками (qcheck.py, qcheck2.py) после сокращения до 25 часов."""
import os, re, sys
A = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'adp2') + '/'
def sub(n, a, b, line=None, cnt=1):
    p = A + 'q%03d.txt' % n; L = open(p, encoding='utf-8').read().split('\n')
    if line:
        assert L[line - 1].count(a) == cnt, (n, line, a, L[line - 1].count(a)); L[line - 1] = L[line - 1].replace(a, b)
        open(p, 'w', encoding='utf-8').write('\n'.join(L))
    else:
        t = '\n'.join(L); assert t.count(a) == cnt, (n, a, t.count(a)); open(p, 'w', encoding='utf-8').write(t.replace(a, b))
# 1. Название приказа МВД России № 205 — по тексту приказа
