# 5. Сокращённые названия, оставшиеся без введения «далее —» (найдено seam25.py после исправления abbr_used)
K = 'Кодекса Российской Федерации об административных правонарушениях//'
def first(n, a, b):
    p = A + 'q%03d.txt' % n; t = open(p, encoding='utf-8').read(); assert a in t, (n, a); open(p, 'w', encoding='utf-8').write(t.replace(a, b, 1))
first(6, '//п. 6.5 Кодекса этики//', '//п. 6.5 Кодекса этики и служебного поведения сотрудников органов внутренних дел Российской Федерации, утв. приказом МВД России от 26.06.2020 № 460//')
first(19, '//ст. 23.3 КоАП РФ//', '//ст. 23.3 ' + K + ' (далее — КоАП РФ)')
first(61, '(//ч. 1 ст. 27.1 КоАП РФ//)', '(//ч. 1 ст. 27.1 ' + K + ', далее — КоАП РФ)')
first(63, '(//ст. 24.1 КоАП РФ//)', '(//ст. 24.1 ' + K + ', далее — КоАП РФ)')
first(69, '(//п. 3 ч. 1 ст. 25.11 КоАП РФ//)', '(//п. 3 ч. 1 ст. 25.11 ' + K + ', далее — КоАП РФ)')
first(71, '**Взаимодействие с Росгвардией.**', '**Взаимодействие с Федеральной службой войск национальной гвардии Российской Федерации (далее — Росгвардия).**')
def after_full(n, key, ab):
    """дописать «(далее — ab)» после полного названия //…key…//"""
    p = A + 'q%03d.txt' % n; t = open(p, encoding='utf-8').read(); i = t.index(key); j = t.index('//', i) + 2
    assert 'далее' not in t[j:j + 12], (n, t[j:j + 30]); open(p, 'w', encoding='utf-8').write(t[:j] + ' (далее — %s)' % ab + t[j:])
after_full(8, 'Кодекс этики и служебного поведения', 'Кодекс этики')
after_full(16, 'от 30.11.2011 № 342-ФЗ', 'Закон о службе')
after_full(47, 'от 31.07.2020 № 248-ФЗ', 'Закон № 248-ФЗ')
after_full(125, 'от 10.01.2002 № 7-ФЗ', 'Закон № 7-ФЗ')
